各模块间通过明确的函数签名、显式参数装配与原生事件契约进行交互解耦，提供变量全定义、无 ReferenceError 风险、内部自洽且可直接指导编码实现的完整开发接口契约与伪代码实现：

```javascript
// 全局状态管理
let activeInputNode = null;
let inputGeneration = 1;

// DOM 元素引用（由 AppController 初始化显式获取并管理）
let displayElement = null;
let errorContainer = null;
let globalBannerElement = null;

// 1. DebounceScheduler 模块接口契约
const DebounceScheduler = (() => {
  let pendingTimerId = null;
  let schedulerEpoch = 0;

  function schedule(draftSnapshot, targetNode, targetGeneration, callback, delayMs = 300) {
    cancel(); // 清除排队任务并递增 schedulerEpoch 使旧回调失效
    const thisEpoch = ++schedulerEpoch;
    pendingTimerId = window.setTimeout(() => {
      // 唤醒守卫：即便回调已出队进入宏任务，若纪元、代际或节点不匹配，立即作废返回
      if (thisEpoch !== schedulerEpoch) return;
      if (targetGeneration !== inputGeneration) return;
      if (targetNode !== activeInputNode) return;
      if (!document.body.contains(targetNode)) return;

      pendingTimerId = null;
      // 严格使用捕获的草稿快照进行校验与输出，绝不重读可能已被篡改的 DOM value
      callback(draftSnapshot);
    }, delayMs);
  }

  function cancel() {
    if (pendingTimerId !== null) {
      window.clearTimeout(pendingTimerId);
      pendingTimerId = null;
    }
    schedulerEpoch++; // 递增纪元使任何待执行或已出队的旧定时器失效
  }

  function isPending() {
    return pendingTimerId !== null;
  }

  function getEpoch() {
    return schedulerEpoch;
  }

  return { schedule, cancel, isPending, getEpoch };
})();

// 2. FeedbackBanner 模块接口契约（错误提示与容错横幅管理）
const FeedbackBanner = (() => {
  function showInputError(inputNode, container, message) {
    if (inputNode) {
      inputNode.setAttribute('aria-invalid', 'true');
      inputNode.classList.add('input-error');
    }
    if (container) {
      container.textContent = message;
      container.classList.remove('hidden');
    }
  }

  function clearInputError(inputNode, container) {
    if (inputNode) {
      inputNode.removeAttribute('aria-invalid');
      inputNode.classList.remove('input-error');
    }
    if (container) {
      container.textContent = '';
      container.classList.add('hidden');
    }
  }

  function showGlobalError(message) {
    if (globalBannerElement) {
      globalBannerElement.textContent = message;
      globalBannerElement.classList.remove('hidden');
    } else {
      console.warn('Global banner:', message);
    }
  }

  function clearGlobalError() {
    if (globalBannerElement) {
      globalBannerElement.textContent = '';
      globalBannerElement.classList.add('hidden');
    }
  }

  return { showInputError, clearInputError, showGlobalError, clearGlobalError };
})();

// 3. DisplayRenderer 模块接口契约（纯文本安全渲染器）
const DisplayRenderer = (() => {
  function renderProjectName(targetElement, text) {
    if (!targetElement) return;
    targetElement.textContent = text;
    targetElement.classList.remove('placeholder');
    targetElement.classList.add('active-result');
  }

  function renderPlaceholder(targetElement, placeholder = '【等待输入核对】') {
    if (!targetElement) return;
    targetElement.textContent = placeholder;
    targetElement.classList.remove('active-result');
    targetElement.classList.add('placeholder');
  }

  return { renderProjectName, renderPlaceholder };
})();

// 4. ValidatorModule 模块接口契约（无状态规则校验器）
const ValidatorModule = (() => {
  function validate(rawInput) {
    if (typeof rawInput !== 'string') {
      return { isValid: false, errorMessage: '项目名不能为空，请输入有效字符' };
    }
    const trimmed = rawInput.trim();
    if (trimmed.length === 0) {
      return { isValid: false, errorMessage: '项目名不能为空，请输入有效字符' };
    }
    return { isValid: true, errorMessage: null };
  }

  return { validate };
})();

// 5. handleDebouncedValidateAndDisplay 防抖执行契约
function handleDebouncedValidateAndDisplay(draftSnapshot) {
  try {
    const validation = ValidatorModule.validate(draftSnapshot);
    if (!validation.isValid) {
      // 空值或纯空格：彻底清除旧项目名展示并恢复占位符，挂载错误提示，输入框草稿完好保留
      DisplayRenderer.renderPlaceholder(displayElement, '【等待输入核对】');
      FeedbackBanner.showInputError(InputController.getActiveInputNode(), errorContainer, validation.errorMessage);
    } else {
      // 有效非空字符：移除错误提示，通过 textContent 安全输出草稿快照
      FeedbackBanner.clearInputError(InputController.getActiveInputNode(), errorContainer);
      DisplayRenderer.renderProjectName(displayElement, draftSnapshot);
    }
  } catch (err) {
    FeedbackBanner.showGlobalError('处理输入时遇到异常，已为您保留当前输入');
    console.error('防抖回调异常:', err);
  }
}

// 6. InputController 模块接口契约（节点生命周期与事件闭包隔离）
const InputController = (() => {
  function isNodeActiveAndCurrent(e, node, bornGeneration) {
    return e.currentTarget === node &&
           node === activeInputNode &&
           bornGeneration === inputGeneration &&
           document.body.contains(node);
  }

  function bindInputNode(node, bornGeneration) {
    // 节点闭包私有变量
    let isComposing = false;
    let trustedDraft = '';

    node.addEventListener('compositionstart', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      isComposing = true;
      DebounceScheduler.cancel(); // 挂起防抖并使旧纪元失效
    });

    node.addEventListener('compositionend', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      isComposing = false;
      trustedDraft = node.value;
      DebounceScheduler.schedule(trustedDraft, node, bornGeneration, handleDebouncedValidateAndDisplay, 300);
    });

    node.addEventListener('input', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      if (!isComposing && !e.isComposing) {
        trustedDraft = node.value;
        DebounceScheduler.schedule(trustedDraft, node, bornGeneration, handleDebouncedValidateAndDisplay, 300);
      }
    });

    node.addEventListener('beforeinput', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });

    node.addEventListener('keydown', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });

    node.addEventListener('paste', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });
  }

  function replaceInputNode() {
    const oldNode = activeInputNode;
    inputGeneration++;
    const nextGen = inputGeneration;

    const newNode = document.createElement('input');

    // 1. 持久配置复制策略：安全遍历并复制旧节点全部持久 DOM 属性与无障碍配置
    // 覆盖：label 关联 (id, name)、ARIA 属性 (aria-label, aria-describedby, aria-required 等)、
    // 键盘导航 (tabindex)、表现样式 (class, style)、测试与自定义属性 (data-*)
    if (oldNode && oldNode.attributes) {
      for (let i = 0; i < oldNode.attributes.length; i++) {
        const attr = oldNode.attributes[i];
        // 过滤瞬态属性与需单独重置的状态：value 属性及瞬态校验属性 aria-invalid
        if (attr.name === 'value' || attr.name === 'aria-invalid') {
          continue;
        }
        newNode.setAttribute(attr.name, attr.value);
      }
    }

    // 2. 状态重置与规范保障：确保基础输入类型为 text，重置 value 为空字符串
    newNode.type = 'text';
    newNode.value = '';

    // 3. 闭包监听绑定：为新节点绑定独立事件监听闭包（注入全新代际 nextGen，重置私有 isComposing 与 trustedDraft）
    bindInputNode(newNode, nextGen);

    // 4. 物理节点替换与活跃指针更新
    if (oldNode && oldNode.parentNode) {
      oldNode.replaceWith(newNode);
    }
    activeInputNode = newNode;

    return activeInputNode;
  }

  function init(initialNode) {
    activeInputNode = initialNode;
    bindInputNode(activeInputNode, inputGeneration);
  }

  function getActiveInputNode() {
    return activeInputNode;
  }

  function focusInput() {
    if (activeInputNode) activeInputNode.focus();
  }

  return { init, bindInputNode, replaceInputNode, getActiveInputNode, focusInput };
})();

// 7. ResetController 模块接口契约（清空复位控制器）
const ResetController = (() => {
  function handleReset() {
    try {
      // 1. 立即取消待展示防抖任务并废弃调度纪元
      DebounceScheduler.cancel();
      // 2. 递增代际，创建保留五类持久配置的新输入节点物理替换旧节点，绑定新闭包
      const newInputNode = InputController.replaceInputNode();
      // 3. 顶部展示区恢复为占位符
      DisplayRenderer.renderPlaceholder(displayElement, '【等待输入核对】');
      // 4. 清除输入错误提示与瞬态 aria-invalid
      FeedbackBanner.clearInputError(newInputNode, errorContainer);
      // 5. 焦点自动回焦到新输入节点
      InputController.focusInput();
    } catch (err) {
      FeedbackBanner.showGlobalError('重置时遇到异常，界面保持可编辑');
      console.error('清空重置异常:', err);
    }
  }

  return { handleReset };
})();

// 8. AppController 核心应用协调器（装配与初始化）
const AppController = (() => {
  function init() {
    // 显式获取 DOM 引用并初始化模块变量
    displayElement = document.getElementById('project-display');
    errorContainer = document.getElementById('error-container');
    globalBannerElement = document.getElementById('global-banner');
    const initialInput = document.getElementById('project-name-input');
    const resetButton = document.getElementById('btn-reset');

    // 初始化输入控制器（绑定代际 1）
    if (initialInput) {
      InputController.init(initialInput);
    }

    // 绑定清空按钮事件
    if (resetButton) {
      resetButton.addEventListener('click', ResetController.handleReset);
    }

    // 全局未捕获异常兜底防护
    window.addEventListener('error', (event) => {
      FeedbackBanner.showGlobalError('系统遇到异常，已为您保留当前输入');
      console.error('全局未捕获异常:', event.error || event.message);
    });
  }

  return { init };
})();

// 页面加载就绪时启动
document.addEventListener('DOMContentLoaded', AppController.init);
```

9. 规范声明与待验证状态说明：
   - 以上代码为规范实现参考，合成核验仅验证事件契约与静态语法自洽性，不能称为目标应用真实实现已完成测试；
   - 防抖调度延迟测量以前台可见状态（document.visibilityState === 'visible'）为基准；后台标签页唤醒时受调度纪元 thisEpoch 与代际 targetGeneration 严格核验约束，旧任务安全作废；
   - 原生输入法在不同桌面浏览器环境下的事件派发细节与真实重定向行为，留待真机开发验证阶段实测。
